//! Rust port of `url-parser/tests/test15.cpp`.
//!
//! Takes six positional arguments — scheme, host, port, path, query, fragment —
//! builds a `URL` from them with `URL::from_components`, and prints the six
//! components followed by `to_string()` and `is_valid()`, one per line.
//!
//! Build either way; both produce the same binary:
//!   rustc -O test15.rs      # -> ./test15
//!   cargo build --release   # -> ./target/release/test15

#[path = "url_parser/mod.rs"]
mod url_parser;

use url_parser::cstdlib::stoi_or_terminate;
use url_parser::URL;

fn main() {
    let argv: Vec<String> = std::env::args().collect();
    if argv.len() < 7 {
        std::process::exit(1);
    }

    let scheme = &argv[1];
    let host = &argv[2];
    // `test15.cpp` calls `std::stoi` with no `try` block, so a port argument
    // that is not a number aborts the process instead of reporting an error.
    let port = stoi_or_terminate(&argv[3]);
    let path = &argv[4];
    let query = &argv[5];
    let fragment = &argv[6];

    let parser = URL::from_components(scheme, host, port, path, query, fragment);

    println!("{}", parser.scheme());
    println!("{}", parser.host());
    println!("{}", parser.port());
    println!("{}", parser.path());
    println!("{}", parser.query());
    println!("{}", parser.fragment());
    println!("{}", parser);
    // `std::cout << bool` prints 1 or 0, not "true"/"false".
    println!("{}", i32::from(parser.is_valid()));
}
