            ("080", 80),
            ("+80", 80),
            (" 80", 80),
            ("\t80", 80),
            ("80 ", 80),
            ("8 0", 8),
            ("80abc", 80),
            ("80.9", 80),
            ("0x50", 0),
            ("1e3", 1),
            ("-0", 0),
            ("  -42xyz", -42),
            ("-1", -1),
